    <aside class="panel media-library-help"><span class="media-library-help__icon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="3"/><circle cx="9" cy="9" r="1.5"/><path d="m6 17 4-4 3 3 2-2 3 3"/></svg></span><h2>File manager workflow</h2><p>Folders and display settings are shared with every page editor.</p><ul><li>Create a folder, then choose it before uploading.</li><li>Use the view menu for icons, list, details, tiles or content.</li><li>Search and sort without losing your current folder.</li></ul></aside>
    <div class="media-modal" data-media-modal hidden><div class="media-modal__card" role="dialog" aria-modal="true" aria-labelledby="media-modal-title"><h2 id="media-modal-title" data-media-modal-title>Delete folder?</h2><p data-media-modal-message></p><form class="media-modal__rename-form" method="post" data-media-rename-form><div class="field media-modal__field"><label for="media-modal-folder">New folder name</label><input class="input" id="media-modal-folder" name="folder" maxlength="100" data-media-modal-input></div>@csrf @method('PATCH')</form><div class="media-modal__actions"><button class="button button--quiet" type="button" data-media-modal-cancel>Cancel</button><button class="button button--danger" type="button" data-media-modal-confirm>Delete folder</button></div></div></div>
@endsection

@push('scripts')
<script>
    (() => {
        const input = document.querySelector('[data-media-file]');
        const dropzone = document.querySelector('[data-media-dropzone]');
        const preview = document.querySelector('[data-media-preview]');
        const view = document.querySelector('#media-view');
        if (view) view.addEventListener('change', () => document.querySelector('#media-filters')?.requestSubmit());
        const back = document.querySelector('[data-media-back]');
        if (back) back.addEventListener('click', (event) => {
            let cameFromMedia = false;
            try { cameFromMedia = window.history.length > 1 && document.referrer && new URL(document.referrer).pathname === window.location.pathname; } catch (_) {}
            if (cameFromMedia) { event.preventDefault(); window.history.back(); }
        });
        const modal = document.querySelector('[data-media-modal]');
        const modalTitle = modal?.querySelector('[data-media-modal-title]');
        const modalMessage = modal?.querySelector('[data-media-modal-message]');
        const modalInput = modal?.querySelector('[data-media-modal-input]');
        const renameForm = modal?.querySelector('[data-media-rename-form]');
        const modalConfirm = modal?.querySelector('[data-media-modal-confirm]');
        let pendingDeleteForm = null;
        let modalMode = 'delete';
        let previousFocus = null;
        const closeModal = () => { if (!modal) return; modal.hidden = true; modal.classList.remove('media-modal--rename'); pendingDeleteForm = null; previousFocus?.focus?.(); };
        const openDeleteModal = (form) => { if (!modal) return; pendingDeleteForm = form; modalMode = 'delete'; previousFocus = document.activeElement; const name = form.dataset.folderName || 'this folder'; modalTitle.textContent = 'Delete folder?'; modalMessage.textContent = `Delete “${name}”? Any images inside will be moved to General.`; modalConfirm.textContent = 'Delete folder'; modal.classList.remove('media-modal--rename'); modal.hidden = false; modalConfirm.focus(); };
        const openRenameModal = (button) => { if (!modal || !renameForm) return; modalMode = 'rename'; pendingDeleteForm = null; previousFocus = document.activeElement; modalTitle.textContent = 'Rename folder'; modalMessage.textContent = `Choose a new name for “${button.dataset.folderName || 'this folder'}”.`; modalConfirm.textContent = 'Rename folder'; renameForm.action = button.dataset.folderRenameAction; modalInput.value = button.dataset.folderName || ''; modal.classList.add('media-modal--rename'); modal.hidden = false; modalInput.focus(); modalInput.select(); };
        document.querySelectorAll('[data-folder-menu-toggle]').forEach((toggle) => toggle.addEventListener('click', (event) => { event.stopPropagation(); const menu = document.getElementById(toggle.getAttribute('aria-controls')); const willOpen = menu?.hidden !== false; document.querySelectorAll('.media-folder__menu').forEach((item) => { item.hidden = true; }); document.querySelectorAll('[data-folder-menu-toggle]').forEach((item) => item.setAttribute('aria-expanded', 'false')); if (menu && willOpen) { menu.hidden = false; toggle.setAttribute('aria-expanded', 'true'); } }));
        document.addEventListener('click', (event) => { if (!event.target.closest('.media-folder__actions')) { document.querySelectorAll('.media-folder__menu').forEach((item) => { item.hidden = true; }); document.querySelectorAll('[data-folder-menu-toggle]').forEach((item) => item.setAttribute('aria-expanded', 'false')); } });
        document.querySelectorAll('[data-folder-rename]').forEach((button) => button.addEventListener('click', () => { button.closest('.media-folder__menu').hidden = true; openRenameModal(button); }));
        document.querySelectorAll('[data-delete-folder]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); form.closest('.media-folder__menu').hidden = true; openDeleteModal(form); }));
        modal?.querySelector('[data-media-modal-cancel]')?.addEventListener('click', closeModal);
        modal?.addEventListener('click', (event) => { if (event.target === modal) closeModal(); });
        modalConfirm?.addEventListener('click', () => { if (modalMode === 'delete' && pendingDeleteForm) { HTMLFormElement.prototype.submit.call(pendingDeleteForm); return; } if (modalMode === 'rename' && renameForm) { if (!modalInput.value.trim()) { modalInput.focus(); return; } HTMLFormElement.prototype.submit.call(renameForm); } });
        document.addEventListener('keydown', (event) => { if (event.key === 'Escape') { if (modal && !modal.hidden) closeModal(); else document.querySelectorAll('.media-folder__menu').forEach((item) => { item.hidden = true; }); } });
        if (!input || !dropzone || !preview) return;
        function showFile() { const files = [...(input.files || [])]; if (!files.length) return; const file = files[0]; preview.querySelector('img').src = URL.createObjectURL(file); preview.querySelector('[data-media-file-name]').textContent = files.length === 1 ? file.name : `${files.length} images selected`; preview.querySelector('[data-media-file-size]').textContent = files.length === 1 ? `${(file.size / 1024 / 1024).toFixed(2)} MB` : 'Ready for batch upload'; preview.classList.add('is-visible'); }
        dropzone.addEventListener('click', () => input.click());
        dropzone.addEventListener('keydown', (event) => { if (!['Enter', ' '].includes(event.key)) return; event.preventDefault(); input.click(); });
        ['dragenter', 'dragover'].forEach((name) => dropzone.addEventListener(name, (event) => { event.preventDefault(); dropzone.classList.add('is-dragging'); }));
        ['dragleave', 'drop'].forEach((name) => dropzone.addEventListener(name, (event) => { event.preventDefault(); dropzone.classList.remove('is-dragging'); }));
        dropzone.addEventListener('drop', (event) => { if (!event.dataTransfer?.files?.length) return; input.files = event.dataTransfer.files; showFile(); });
        input.addEventListener('change', showFile);
    })();
</script>
@endpush
